      "type": "boolean",
      "title": "Animate while working",
      "description": "Move the colours across the row while a turn runs, and blink a figure at its warning level.",
      "default": true
    },
    "placement": {
      "type": "string",
      "title": "Where the row is drawn",
      "description": "Below the prompt, above Claude Code's hint line, or in the band above the prompt.",
      "options": [
        "below",
        "above"
      ],
      "default": "below"
    },
    "hide": {
      "type": "string",
      "title": "Segments to hide",
      "description": "Comma-separated, from: model, effort, context, limits, turn, tools, agents, git, cost, session, folder.",
      "default": ""
    }
  }
}

